-- Every card gets its effect. Spells and traps the engine had no op for get
-- one, and every monster whose ability was pending gets its "abilities" (see
-- game/engine/abilities.go). Monsters whose text describes a fusion recipe
-- (Metalmorph, Cocoon of Evolution) need nothing: the fusion table does it.
-- A card someone has already changed through the card admin is left as it is.

UPDATE cards SET data = json_remove(json_set(data, '$.abilities', json('[{"op":"battleBonus","types":["fiend"],"amount":300}]')), '$.abilityPending') WHERE num = 1 AND json_extract(data, '$.abilityPending') = 1;
